    {"id": "v03-dvor", "cat": "shop", "tier": "several", "priority": 3, "badge": "GAULT&MILLAU 16", "name": "Dvor", "neighborhood": "Firule", "short": "Dvor", "lat": 43.50412, "lng": 16.45582, "tags": [], "productTags": ["Michelin"], "why": "Dvor sits on Put Firula, a fifteen-minute walk east of the palace, on a terrace facing the water, so the view is open sea and the islands rather than the port. The kitchen, led in Gault&Millau's 2026 entry by Vesna Vukman, mixes the Mediterranean and the traditional: reviewers keep returning to a ceviche of fish, scampi and scallops in a citrus emulsion, and to a prawn carpaccio. Gault&Millau scores it 16/20.", "address": "Put Firula 14, Split", "phone": "+385 21 571 513", "hours": "Seasonal with a winter break: an older Split article says it reopens after the winter pause in late February or early March; 2026 closing date not found. Probably trading now (23 Oct); November-December uncertain, call ahead. Reopening 2027 not announced · In Your Pocket (May 2026 version): 12:00-24:00; winter hours not published", "maps": "https://www.google.com/maps/search/?api=1&query=Dvor+Split", "price_range": "MICHELIN €€€€ (seen Oct 2026)", "status": "confirmed", "statusChecked": "2026-10-23", "hook": "Sea terrace at Firule, east of the centre, looking out over the open channel to the islands.", "verdict": "The sea-terrace night of the three, and the quieter one: you leave the old town behind and eat facing the open water. MICHELIN puts it in its top price bracket, and Gault&Millau ranks it just behind ZOI. It has historically taken a winter break, so it belongs to an October evening, not a December one, unless the house confirms otherwise.", "signature": "The fish, scampi and scallop ceviche in citrus emulsion, at sunset", "caveat": "Historically closes for a winter break and reopens late Feb or early March; 2026-27 dates not found, call ahead", "person": "Vesna Vukman (chef, Gault&Millau 2026)", "dishes": [{"name": "Ceviche of fish, scampi and scallops", "note": "In citrus emulsion; the plate reviewers name first", "kind": "dish"}, {"name": "Prawn carpaccio", "note": "Raw Adriatic prawn, thin-sliced", "kind": "dish"}, {"name": "Grilled whole fish", "note": "Listed by guides and in our May 2026 record", "kind": "dish"}, {"name": "Rack of lamb", "note": "The meat choice listed by guides", "kind": "dish"}, {"name": "Brodet", "note": "Dalmatian fish stew, from the May 2026 record; ask if on", "kind": "dish"}], "reservation": "Recommended; ask for the sea-view terrace", "signal_chip": {"label": "G&M 16/20", "full": "Gault&Millau Croatia 2026: 16/20, Remarkable Restaurant; has a MICHELIN Guide page (€€€€), 2026 selection status not dated in extracts", "cosign": "Chef Vesna Vukman (Gault&Millau 2026)"}, "category": "summit"},
    {"id": "v04-konoba-fetivi", "cat": "shop", "tier": "several", "priority": 4, "badge": "MICHELIN SELECTED", "name": "Konoba Fetivi", "neighborhood": "Veli Varoš", "short": "Konoba Fetivi", "lat": 43.50882, "lng": 16.43352, "tags": [], "productTags": ["Michelin"], "why": "Fetivi is the Split word for the true-born locals, and the konoba on Tomića stine works the way its name promises. MICHELIN's inspectors note that the raw catch is carried to each table so you can pick your fish before it goes on the grill. The menu is short and traditional and the prices modest; Gault&Millau's 2026 reviewer singles out a creamy, thick black cuttlefish risotto, and Falstaff adds tuna steak and squid stew.", "address": "Tomića stine 4, Split", "phone": "+385 21 355 152", "hours": "No seasonal closure found; season and winter hours not published. Likely trading now (23 Oct); November-December unconfirmed · Call ahead: Bookiscout 12:00-23:00, closed Sun; Tablejourney Tue-Sun 12:00-23:00, closed Mon; Falstaff notes Sunday opening", "maps": "https://www.google.com/maps/search/?api=1&query=Konoba+Fetivi+Split", "price_range": "MICHELIN €€ (seen Oct 2026)", "status": "confirmed", "statusChecked": "2026-10-23", "hook": "Varoš konoba where the day's catch comes to the table on a plate before you choose it.", "verdict": "The one Varoš konoba with both MICHELIN and Gault&Millau behind it in 2026, and still priced like a neighbourhood room. Choose the fish from the plate, take the black risotto, drink the house white. It is small and popular, so book; and confirm the closing day, because the listings disagree.", "signature": "Black cuttlefish risotto, then a fish chosen from the plate", "caveat": "Book ahead; closing day disputed (Sunday or Monday), call first", "person": "Frane Orlić (chef, Gault&Millau 2026)", "dishes": [{"name": "Crni rižot", "note": "Black cuttlefish risotto, praised by MICHELIN and Gault&Millau", "kind": "dish"}, {"name": "Fish of the day, grilled", "note": "Chosen raw from the plate brought to the table", "kind": "dish"}, {"name": "Pasta with shrimp", "note": "Named by Falstaff 2026", "kind": "dish"}, {"name": "Tuna steak", "note": "Named by Falstaff 2026", "kind": "dish"}, {"name": "Squid stew", "note": "Named by Falstaff 2026", "kind": "dish"}, {"name": "Gregada", "note": "Hvar-style fish and potato stew, from the May 2026 record; ask if on", "kind": "dish"}], "reservation": "Advised (MICHELIN)", "signal_chip": {"label": "MICHELIN 2026", "full": "Selected in the MICHELIN Guide Croatia 2026 (no star, no Bib); Gault&Millau Croatia 2026 13/20; Falstaff 2026 85 points", "cosign": "Chef Frane Orlić (Gault&Millau 2026)"}, "category": "varos", "charter": {"price": "MICHELIN €€ (seen Oct 2026)", "book": "Advised (MICHELIN)", "warn": "Book ahead; closing day disputed (Sunday or Monday), call first", "fit": "Varoš konoba where the day's catch comes to the table on a plate before you choose it."}},
    {"id": "v08-konoba-matejuska", "cat": "shop", "tier": "several", "priority": 8, "badge": "FISH BY WEIGHT", "name": "Konoba Matejuška", "neighborhood": "Matejuška", "short": "Konoba Matejuška", "lat": 43.50822, "lng": 16.43432, "tags": [], "productTags": ["Traditional"], "why": "Konoba Matejuška takes its name from the little harbour below it, where Split's fishermen still tie up their boats, and it cooks the catch the same way they would: grilled, priced by weight, shown to you before it goes on the coals. The room is small and family-run, the terrace on Tomića stine fills early, and Time Out's reviewer pointed first to the tuna marinated in red wine and herbs as a starter to share.", "address": "Tomića stine 3, Split", "phone": "", "hours": "Not published; no 2026 dates found. Open now (23 Oct) and in November-December unconfirmed · Call ahead: Foodle and Tablejourney give Mon-Tue 17:00-23:00, Wed-Sun 11:00-23:00; Time Out gives 08:00-23:00 daily", "maps": "https://www.google.com/maps/search/?api=1&query=Konoba+Matejuška+Split", "price_range": "EUR 30-50 mains (seen May 2026)", "status": "unverified", "statusChecked": "2026-10-23", "hook": "Family grill a few steps above the fishermen's harbour, fish sold by weight from what came in that day.", "verdict": "An honest fisherman's grill rather than a destination, and useful for exactly that: a late, simple fish dinner close to the harbour. We found nothing dated 2026, so treat it as likely but unconfirmed, and call before sending guests. Bring cash.", "signature": "Tuna marinated in red wine and herbs, then grilled fish by weight", "caveat": "No 2026 evidence found; cash preferred; small terrace fills early", "dishes": [{"name": "Marinated tuna", "note": "In red wine and herbs, a starter to share (Time Out)", "kind": "dish"}, {"name": "Grilled fish by weight", "note": "Pick from the day's catch", "kind": "dish"}, {"name": "Crni rižot", "note": "Black cuttlefish risotto, named by reviewers", "kind": "dish"}, {"name": "House wine", "note": "Cheap and good, per Time Out", "kind": "drink"}], "reservation": "Advised in summer; go for 19:30 or 21:30", "signal_chip": {"label": "Family grill", "full": "Family-run fish grill by the Matejuška harbour; no MICHELIN or Gault&Millau 2026 listing found", "cosign": "Time Out Croatia, 4/5 (undated)"}, "category": "varos"},
    {"id": "v11-sperun", "cat": "shop", "tier": "several", "priority": 11, "badge": "VAROŠ KONOBA", "name": "Šperun Eat and Drink", "neighborhood": "Veli Varoš", "short": "Šperun", "lat": 43.50762, "lng": 16.43592, "tags": [], "productTags": ["Traditional"], "why": "Šperun takes its name from the short street at the edge of Veli Varoš where it stands, at number 3, a few minutes' walk from the Riva. It runs as a casual konoba with a small terrace, grilling Adriatic fish every day and pouring local wine late into the evening. Reviewers through the summer of 2026 still came back for the tuna and the staff; the menu stays plain: sardines, a whole sea bass, grilled squid.", "address": "Šperun 3, Split", "phone": "", "hours": "No seasonal closure found; 2026 trading confirmed by June 2026 reviews. Open now (23 Oct) and November-December unconfirmed · Call ahead: own site lists 11:00-24:00 (incl. Monday); Tablejourney 09:00-24:00, closed Mondays; Tripadvisor closes 23:00", "maps": "https://www.google.com/maps/search/?api=1&query=Šperun+Split", "price_range": "EUR 25-40 mains (seen May 2026)", "status": "confirmed", "statusChecked": "2026-10-23", "hook": "Small-terrace Varoš konoba on the street it is named after, grilled sardines and local wine until midnight.", "verdict": "A dependable, unpretentious table for a casual night, not a culinary event: ratings are solid rather than high, and one June 2026 reviewer found the pasta heavy. Stick to the grill, take the terrace, and use it when the better-known Varoš houses are full.", "signature": "Grilled sardines with a glass of local white", "caveat": "Book the terrace in July-August; hours conflict, call ahead", "dishes": [{"name": "Grilled sardines", "note": "The simplest Varoš plate", "kind": "dish"}, {"name": "Whole sea bass", "note": "From the grill", "kind": "dish"}, {"name": "Grilled squid", "note": "Listed among its signatures", "kind": "dish"}, {"name": "Tuna", "note": "Praised in 2026 reviews", "kind": "dish"}], "web": "https://sperun.eatbu.hr", "reservation": "Book the terrace in July-August", "signal_chip": {"label": "Varoš grill", "full": "Casual Varoš konoba; Tripadvisor 4.0 from about 950 reviews; no MICHELIN or Gault&Millau listing found", "cosign": "Dated Tripadvisor reviews, June 2026"}, "category": "varos"},
    {"id": "v06-apetit", "cat": "shop", "tier": "several", "priority": 6, "badge": "PALACE UPSTAIRS", "name": "Apetit", "neighborhood": "Palace", "short": "Apetit", "lat": 43.50942, "lng": 16.44122, "tags": [], "productTags": ["Contemporary"], "why": "You climb from a narrow lane into the 15th-century Papalić Palace, the Gothic townhouse that also holds the city museum, and Apetit occupies an upper floor, quiet above the crowds below. The kitchen keeps to Dalmatian classics, cooked simply with a small twist: pašticada, homemade pasta, and the offal the tourist menus skip, tongue and tripe. Diners also remember the bread and olive oil set down first.", "address": "Šubićeva 5, Split (Split Curated gives Ulica Pavla Šubića 2)", "phone": "", "hours": "No seasonal closure found; season not published. Likely trading now (23 Oct); November-December unconfirmed · Call ahead: In Your Pocket (March 2026 listing) 11:00-24:00; a 2024 listing gave 09:00-24:00", "maps": "https://www.google.com/maps/search/?api=1&query=Apetit+Split", "price_range": "EUR 30-50 mains (seen May 2026)", "status": "confirmed", "statusChecked": "2026-10-23", "hook": "Dalmatian classics upstairs in the 15th-century Papalić Palace, above the lanes of the old town.", "verdict": "A calm, mid-to-upper-priced lunch inside the palace quarter, good when guests want the old dishes without the street noise. Reviews are mixed on consistency and service, and no guide rates it in 2026, so take it for the room and the pašticada rather than for ambition.", "signature": "Pašticada with homemade pasta", "caveat": "Upper floor, stairs only (floor disputed); no guide rating in 2026", "dishes": [{"name": "Pašticada", "note": "Wine-braised Dalmatian beef, the plate reviewers praise", "kind": "dish"}, {"name": "Homemade pasta", "note": "Paired with the pašticada", "kind": "dish"}, {"name": "Tongue", "note": "One of the offal dishes Time Out noted", "kind": "dish"}, {"name": "Tripe", "note": "Old Split cooking, rarely offered in the centre", "kind": "dish"}], "reservation": "Advised in season", "signal_chip": {"label": "Papalić Palace", "full": "Upper-floor dining room in the 15th-century Papalić Palace; no MICHELIN or Gault&Millau 2026 listing found", "cosign": "Time Out Croatia, 4/5 (older review)"}, "category": "palace", "hot_this_month": "Dalmatian pašticada, a winter dish, on a quiet first floor away from the cruise-day crowds (checked 23 Oct 2026)."},
    {"id": "v12-villa-spiza", "cat": "berth", "tier": "berth_top", "priority": 2, "badge": "CASH, NO BOOKINGS", "name": "Villa Spiza", "neighborhood": "Palace", "short": "Villa Spiza", "tags": [], "productTags": ["Cult"], "why": "Villa Spiza is one small room with a counter and a kitchen squeezed into one side, on Kružićeva inside the palace. Ivana Gamulin, daughter of the Split chef Nikica Gamulin, cooks what she bought that morning at the market and the fish hall, and her sister Nada makes the desserts. The board changes daily, with grilled fish, black risotto and homemade pasta with seafood or mushrooms, and when a dish runs out it is gone.", "address": "Kružićeva 3 (Petra Kružića 3), Split", "phone": "", "hours": "Year-round with shorter winter hours (per Frankaboutcroatia, undated): summer daily 13:00-24:00; winter Mon 12:00-15:15, Tue-Sat 13:00-22:00, Sun closed. Likely trading now (23 Oct) and into November-December on winter hours; confirm on its social pages · Call ahead: winter Mon 12:00-15:15, Tue-Sat 13:00-22:00, closed Sun; summer daily 13:00-24:00 (guides, undated); owners post changes on social media and Google Maps", "maps": "https://www.google.com/maps/search/?api=1&query=Villa+Spiza+Split", "price_range": "About EUR 25-40 per person (Frankaboutcroatia, undated)", "reservation": "None; walk in, arrive early", "status": "confirmed", "statusChecked": "2026-10-23", "hook": "Tiny counter kitchen in the palace lanes, menu written each morning from the market; no bookings, cash only.", "verdict": "The best-value plate inside the walls and the one with a queue to prove it: in summer the wait can reach two hours. Come early, bring cash, accept what is on the board. In late autumn the line shortens, but the hours shrink too, so check its social pages on the day.", "signature": "Whatever fish is on the board, then Nada's chocolate cake", "caveat": "No reservations, cash only; winter hours shorter and closed Sundays", "person": "Ivana Gamulin (chef-owner)", "dishes": [{"name": "Grilled fish", "note": "From the morning fish market", "kind": "dish"}, {"name": "Crni rižot", "note": "Black cuttlefish risotto, a regular on the board", "kind": "dish"}, {"name": "Homemade pasta with seafood or mushrooms", "note": "Diners single out the mushroom version", "kind": "dish"}, {"name": "Artichokes", "note": "Praised by Falstaff", "kind": "dish"}, {"name": "Chocolate cake", "note": "Nada's dessert, named by Falstaff", "kind": "sweet"}], "signal_chip": {"label": "No bookings", "full": "Walk-in counter kitchen inside the palace; Gault&Millau Croatia 2026 entry (Popular, no score shown in extracts); Falstaff 84 points (2025)", "cosign": "Andrew Zimmern recommends it"}, "category": "palace", "charter": {"price": "About EUR 25-40 per person (Frankaboutcroatia, undated)", "book": "None; walk in, arrive early", "warn": "No reservations, cash only; winter hours shorter and closed Sundays", "fit": "Tiny counter kitchen in the palace lanes, menu written each morning from the market; no bookings, cash only."}},
    {"id": "v05-bokeria-kitchen-wine", "cat": "shop", "tier": "several", "priority": 5, "badge": "GAULT&MILLAU 13.5", "name": "Bokeria Kitchen & Wine", "neighborhood": "Centre (fish market)", "short": "Bokeria Kitchen & Wine", "lat": 43.50862, "lng": 16.44032, "tags": [], "productTags": ["Contemporary"], "why": "Bokeria borrows its name from the market hall of a big Spanish city and sits, fittingly, next to Split's own fish market on Domaldova, just west of the palace. Large glass walls blur the line between the street and the long room, and shelves of bottles climb the walls. Gault&Millau's 2026 reviewer notes it fills from morning to late at night; diners keep naming the octopus, the risotto, the carpaccio and the sea bass.", "address": "Domaldova 8, Split", "phone": "", "hours": "No seasonal closure found; season and winter hours not published. Likely trading now (23 Oct); November-December unconfirmed · Call ahead: hours not re-checked; reviews describe it open from the morning to late", "maps": "https://www.google.com/maps/search/?api=1&query=Bokeria+Kitchen+&+Wine+Split", "price_range": "EUR 35-60 mains (seen May 2026)", "status": "confirmed", "statusChecked": "2026-10-23", "hook": "Glass-fronted wine bistro beside the fish market, open from morning to late, walls lined with bottles.", "verdict": "A reliable, well-run modern bistro with a serious Croatian wine list, more useful for its hours and its bottles than for any single plate. Reviewers find the presentation stronger than some of the flavours, and prices sit above the Split average. Book, especially for dinner.", "signature": "Octopus, with a Croatian bottle chosen from the walls", "caveat": "Reserve even off-season; prices above the local average", "person": "Željka Bogdan (chef, Gault&Millau 2026)", "dishes": [{"name": "Octopus", "note": "The dish diners name most often", "kind": "dish"}, {"name": "Risotto", "note": "A repeat favourite in reviews", "kind": "dish"}, {"name": "Carpaccio", "note": "Named in reviews", "kind": "dish"}, {"name": "Sea bass", "note": "The fish plate reviewers return to", "kind": "dish"}, {"name": "Fish tacos", "note": "The casual plate at the bar", "kind": "dish"}, {"name": "Croatian wine by the glass", "note": "The wall of bottles is the point", "kind": "drink"}], "reservation": "Recommended (Gault&Millau 2026)", "signal_chip": {"label": "G&M 13.5/20", "full": "Gault&Millau Croatia 2026: 13.5/20 (same in 2025); not found in the MICHELIN Guide", "cosign": "Chef Željka Bogdan (Gault&Millau 2026)"}, "category": "palace", "charter": {"price": "EUR 35-60 mains (seen May 2026)", "book": "Recommended (Gault&Millau 2026)", "warn": "Reserve even off-season; prices above the local average", "fit": "Glass-fronted wine bistro beside the fish market, open from morning to late, walls lined with bottles."}},
    {"id": "v17-zinfandel-food-wine-bar", "cat": "shop", "tier": "plenty", "priority": 17, "badge": "MICHELIN GUIDE", "name": "Zinfandel Food & Wine Bistro", "neighborhood": "Centre", "short": "Zinfandel Food & Wine Ba", "lat": 43.50872, "lng": 16.43972, "tags": [], "productTags": ["Wine"], "why": "Zinfandel takes its name from the grape that DNA work traced back to Dalmatia's Tribidrag, and it sits on Marulićeva, a narrow lane off the western edge of the palace. It runs from breakfast to late evening, with live music some nights. The list covers the whole of Croatia with around fifteen wines by the glass, and the kitchen mixes Dalmatian recipes with international plates: pasta in a prošek sauce with prawns, boards of cured meat, cheese and marinated fish.", "address": "Marulićeva 2, Split", "phone": "+385 21 355 135", "hours": "No seasonal closure found; listings give all-week hours. Trading in 2026 (MICHELIN Guide Croatia 2026 listing; Tripadvisor 2026). Open now and in November–December likely but not confirmed · Call ahead: MICHELIN UK page gives Tue–Sat 16:00–24:00, closed Sun and Mon; other MICHELIN locale pages give daily 12:00–24:00; Time Out gives Mon–Thu 08:00–24:00, Fri–Sat 08:00–01:00, closed Sunday", "maps": "https://www.google.com/maps/search/?api=1&query=Zinfandel+Food+&+Wine+Bar+Split", "price_range": "€€ (MICHELIN, seen Oct 2026)", "status": "confirmed", "statusChecked": "2026-10-23", "hook": "A MICHELIN-listed wine bistro in a narrow old-town street, about 15 Croatian wines by the glass.", "verdict": "The most useful glass in the old town now that Paradox is reported closed, and the only wine bar in this guide with a MICHELIN listing in 2026. The food is better than bar snacks, the room is busy and close. Go for a flight of Croatian reds before or after dinner, or make it the dinner itself. Hours vary by source, so call.", "signature": "Pasta with prošek sauce and prawns, with a glass of Tribidrag or Plavac Mali", "caveat": "Hours conflict across sources (some say closed Sunday, some Monday); small room, book at night", "dishes": [{"name": "Pasta with prošek sauce and prawns", "note": "The plate MICHELIN singles out: sweet Dalmatian dessert wine in the sauce", "kind": "dish"}, {"name": "Sharing board", "note": "Cured meats, cheeses and marinated seafood, per Time Out", "kind": "dish"}, {"name": "Croatian wines by the glass", "note": "About 15 open bottles from across Croatia", "kind": "drink"}], "web": "https://www.zinfandelfoodandwinebar.com/", "reservation": "Advised in the evening", "signal_chip": {"label": "MICHELIN", "full": "Selected in the MICHELIN Guide Croatia 2026 (modern cuisine, €€); distinction category not shown in extracts", "cosign": "MICHELIN-recommended 2024 and 2025 per the house and third-party listings"}, "category": "bistro", "hot_this_month": "The bar built around Tribidrag, Zinfandel's Croatian name: the glass to order in the week of Martinje, 11 November (checked 23 Oct 2026).", "charter": {"price": "€€ (MICHELIN, seen Oct 2026)", "book": "Advised in the evening", "warn": "Hours conflict across sources (some say closed Sunday, some Monday); small room, book at night", "fit": "A MICHELIN-listed wine bistro in a narrow old-town street, about 15 Croatian wines by the glass."}},
    {"id": "v02-sug", "cat": "shop", "tier": "several", "priority": 2, "badge": "GAULT&MILLAU 13.5", "name": "Šug", "neighborhood": "Centre (palace north-east)", "short": "Šug", "tags": [], "productTags": ["Michelin"], "why": "The name is the Dalmatian word for a slow, rich sauce, and the kitchen lives up to it: Gault&Millau's 2026 reviewer singles out the tećade, the braised pot dishes, alongside the day's fish. The room is a small stone tavern with a terrace on Tolstojeva, a few steps outside the palace walls. Two chefs, Duje Kanajet and Mateo Kordić, cook traditional recipes with precise, current technique, and the wine list stays mostly local.", "address": "Ulica Lava Nikolajeviča Tolstoja 1a, Split", "phone": "", "hours": "No seasonal closure found; season and winter hours not published in what we found. Likely trading now (23 Oct); November-December unconfirmed · Call ahead: Wolt lists Mon-Sat 10:00-20:30, closed Sun (delivery hours); Petit Futé lists 08:00-23:00", "maps": "https://www.google.com/maps/search/?api=1&query=Šug+Split", "price_range": "MICHELIN €€€ (seen Oct 2026); Gault&Millau calls prices reasonable", "status": "confirmed", "statusChecked": "2026-10-23", "hook": "Small stone tavern just off the palace's north-east corner, Dalmatian pot dishes cooked with a modern hand.", "verdict": "Not a grand table: a small, well-priced house that cooks the Dalmatian repertoire properly, which is rarer in the centre than it should be. Good for a guest who wants pašticada or a rižot without the tourist-menu version. Reservations are mandatory and the room is small, so it fits a last-minute dinner only if you call early.", "signature": "A teća of the day, the slow-braised pot dish", "caveat": "Reservation mandatory; small room; hours conflict across listings, call ahead", "person": "Duje Kanajet and Mateo Kordić (chefs)", "dishes": [{"name": "Tećade", "note": "Braised pot dishes, the house's strength per Gault&Millau 2026", "kind": "dish"}, {"name": "Fresh fish of the day", "note": "Singled out in the 2026 Gault&Millau review", "kind": "dish"}, {"name": "Pašticada with gnocchi", "note": "The Dalmatian Sunday braise, listed among its signatures", "kind": "dish"}, {"name": "Skradinski rižot", "note": "The long-stirred veal risotto from Skradin, on its delivery menu", "kind": "dish"}, {"name": "Crni rižot", "note": "Cuttlefish-ink risotto", "kind": "dish"}, {"name": "Grilled Adriatic tuna", "note": "On its current delivery menu", "kind": "dish"}], "web": "https://sug.hr", "reservation": "Mandatory (Gault&Millau 2026)", "signal_chip": {"label": "G&M 13.5/20", "full": "Gault&Millau Croatia 2026: 13.5/20, Chef's Restaurant; has a MICHELIN Guide page (2026 status not dated in extracts; not a 2026 Bib Gourmand)", "cosign": "Chefs Duje Kanajet and Mateo Kordić"}, "category": "bistro"},
    {"id": "v09-konoba-marjan", "cat": "shop", "tier": "several", "priority": 9, "badge": "FAMILY KONOBA", "name": "Konoba Marjan", "neighborhood": "Veli Varoš", "short": "Konoba Marjan", "lat": 43.50912, "lng": 16.43242, "tags": [], "productTags": ["Traditional"], "why": "Konoba Marjan is a few tables on Senjska, the stepped street in Veli Varoš that climbs toward the Marjan park. Father, mother and son run it, and they say the menu changes daily with what the nearby fish market has to offer. That shows on the board: cuttlefish brujet, gregada with potato, prawn pasta, black risotto, a whole grilled fish deboned at the table. The wine list leans on small Croatian producers.", "address": "Senjska 1, Split", "phone": "", "hours": "Not established: listings give hours without a season; trading spring 2026 (Tripadvisor reviews March–May 2026). Whether it is open now and in November–December is not confirmed · Call ahead: Apple Maps gives Mon–Sat 12:00–22:00, closed Sunday; Time Out gives daily 12:00–22:00; Tripadvisor and Evendo show closing at 23:00", "maps": "https://www.google.com/maps/search/?api=1&query=Konoba+Marjan+Split", "price_range": "EUR 25-45 mains (seen May 2026)", "status": "confirmed", "statusChecked": "2026-10-23", "hook": "A small family konoba at the foot of Marjan hill, cooking whatever the fish market had that morning.", "verdict": "A real fish konoba rather than a palace-front trap, and well loved for its grill. It is small, so it fills and the kitchen runs out: one spring 2026 diner found the black risotto gone by 7:30 pm, and others reported slow service on full nights. Book, come early, and order the fish of the day rather than the menu standards.", "signature": "Whole grilled fish of the day, or cuttlefish brujet", "caveat": "Very few tables: book; dishes sell out by mid-evening; hours differ across listings", "dishes": [{"name": "Cuttlefish brujet", "note": "Dalmatian stew of cuttlefish in a tomato and wine sauce, a listed daily special", "kind": "dish"}, {"name": "Gregada", "note": "White fish stewed with potato, the old fishermen's dish", "kind": "dish"}, {"name": "Black risotto", "note": "Squid-ink risotto; sells out early", "kind": "dish"}, {"name": "Prawn pasta", "note": "Named by Lonely Planet and by reviewers", "kind": "dish"}, {"name": "Grilled fish of the day", "note": "Whole fish from the morning market, deboned at the table", "kind": "dish"}], "reservation": "Recommended; very few covers", "signal_chip": {"label": "Family konoba", "full": "Family-run fish konoba; Tripadvisor 4.5 from about 2,100 reviews, 2025 Travellers' Choice", "cosign": "Lonely Planet lists it as a top choice in Split"}, "category": "locals"},
    {"id": "v-kantun-paulina", "cat": "shop", "tier": "plenty", "priority": 1, "name": "Kantun Paulina", "short": "Kantun Paulina", "tags": [], "productTags": ["Ćevapi"], "address": "Matošića 1, Split", "maps": "https://www.google.com/maps/search/?api=1&query=Kantun+Paulina+Split+Croatia", "why": "Kantun Paulina is a corner hatch on Matošića, a lane parallel to Marmontova, with a few stools and a queue. It has been grilling ćevapi for decades, the start date is argued (1967, 1979, or 'over 37 years'), and it does them the Split way: in a thick, doughy lepinja with ajvar, red pepper relish, and raw onion rather than the kajmak of Sarajevo. Portions come small, medium or large.", "verdict": "The quick meal that locals argue about rather than a sit-down, and good value next to anything on the Riva. Reviews in 2025 still put it among the best ćevapi in town, with a few saying it has slipped. Expect a line, bring cash, eat standing or on the move.", "signature": "A medium portion of ćevapi in lepinja with ajvar and onion", "caveat": "Cash only; queues; few seats; no 2026-dated evidence found", "person": "", "status": "unverified", "statusChecked": "2026-10-23", "hook": "The takeaway ćevapi window on Matošića: grilled meat in a soft lepinja, onion and ajvar, cash only.", "dishes": [{"name": "Ćevapi in lepinja", "note": "Small, medium or large, with onion and ajvar", "kind": "dish"}, {"name": "Ajvar", "note": "Red pepper relish, the Split choice over kajmak", "kind": "dish"}], "hours": "Year-round per listings; open now likely, not confirmed for 2026 · 10:00–23:00 daily (one guide; unconfirmed)", "price_range": "Small EUR 6.50, medium 8.50, large 10.50 (Tripadvisor review, Oct 2025; not re-seen in 2026)", "reservation": "None; takeaway", "neighborhood": "Centre", "signal_chip": {"label": "Ćevapi", "full": "Long-running takeaway ćevapi window, opening year disputed (1967 / 1979)", "cosign": "Total Croatia News: the epitome of Split-style ćevapi"}, "badge": "STREET FOOD", "category": "locals"},
    {"id": "v13-pazar-marche-vert", "cat": "market", "tier": "plenty", "priority": 13, "badge": "MARKET", "name": "Pazar (Green Market)", "neighborhood": "Palace (Silver Gate)", "short": "Pazar (Marché vert)", "lat": 43.50822, "lng": 16.44232, "tags": [], "productTags": ["Market", "Produce"], "why": "Pazar spreads its stalls along the outside of Diocletian's east wall by the Silver Gate, and it is where the city still buys its greens. Family farms (OPG) sell from the central aisles: tomatoes, figs fresh or dried, wild herbs, olive oil, honey, fresh farm cheese at a few euros a kilo next to aged Pag sheep cheese at around 35. The vegetable sellers clear out by early afternoon; at 7 am the best of it is still on the tables.", "address": "Stalls along the east wall of Diocletian's Palace by the Silver Gate (Srebrna vrata), Split", "phone": "", "hours": "Year-round daily market (all listings); open now. In late November–December fritule stalls appear around the market per the old guide (not re-checked) · Call ahead: Tablejourney and Kupi give daily 06:00–14:00; one food guide says it closes by 12:00 on Sundays; Absolute Croatia and Airbnb say it runs into the evening", "maps": "https://www.google.com/maps/search/?api=1&query=Pazar+(Marché+vert)+Split", "price_range": "Produce about EUR 1–6 per kg; cheese about EUR 5–35 per kg (undated guide; not re-seen in Oct 2026)", "reservation": "None", "status": "unverified", "statusChecked": "2026-10-23", "hook": "Split's open-air produce market against the palace's east wall, busiest from dawn to mid-morning.", "verdict": "The place to provision a galley and to see what is in season before choosing a konoba. Go early, carry cash and taste before you buy; the second ring of stalls sells souvenirs and imported fruit. Not a place to eat, but the most honest view of the Dalmatian table in town.", "signature": "Dried figs, Pag cheese and a bottle of local olive oil for the boat", "caveat": "Go before 9:00; stalls thin out by noon; cash", "dishes": [{"name": "Dried figs (suhe smokve)", "note": "Dalmatian figs, dried on the islands", "kind": "sweet"}, {"name": "Paški sir", "note": "Pag sheep cheese, aged; around EUR 35 a kilo in one guide", "kind": "dish"}, {"name": "Seasonal tomatoes and greens", "note": "From family farms in the central aisles", "kind": "dish"}, {"name": "Dalmatian olive oil", "note": "Sold by producers in bottles", "kind": "drink"}], "signal_chip": {"label": "City market", "full": "Split's main open-air green market, daily, by the palace east wall", "cosign": "Old guide: be there at 8 am for the real producers"}, "category": "street", "hot_this_month": "The new olive oil from Brač and Šolta starts to reach the stalls with the harvest; go at 08:00 for the producers, and note the holidays of 1 and 18 November (checked 23 Oct 2026)."},
    {"id": "v14-ribarnica-marche-aux-poiss", "cat": "market", "tier": "plenty", "priority": 14, "badge": "MARKET", "name": "Ribarnica (Fish Market)", "neighborhood": "Marmontova", "short": "Ribarnica (Marché aux po", "tags": [], "productTags": ["Market", "Produce"], "why": "Locals call it peškarija. The fish hall sits just off Marmontova, a short walk from the sulphur springs of the old spa, and local legend says the sulphur keeps the flies away. The marble counters carry what the boats brought in: whole sea bass and bream, octopus sold by weight, cuttlefish, scampi for the grill, small oily fish for frying. It is a working market; by early afternoon the counters are hosed down.", "address": "Kraj Sv. Marije, off Marmontova, Split", "phone": "", "hours": "Year-round market (all listings); open now on weekday mornings · Call ahead: Time Out gives Mon–Sat 06:30–13:30, Sun 06:30–12:00; In Your Pocket (May 2025) gives 06:00–13:00, Sun from 07:00; Tablejourney gives Mon–Sat 07:00–13:00, closed Sunday", "maps": "https://www.google.com/maps/search/?api=1&query=Ribarnica+(Marché+aux+poissons)+Split", "price_range": "EUR variable (seen May 2026)", "reservation": "None", "status": "unverified", "statusChecked": "2026-10-23", "hook": "The morning fish market off Marmontova, cash on the counter and the best fish gone before nine.", "verdict": "Go before the konoba lunch to learn what is in season and what it costs before you see it on a menu. Buyers for galleys can deal here directly, in cash. The best whole fish go before 9:00. Do not come after 13:00, and check Sunday before you plan around it.", "signature": "Whole line-caught fish, bought by weight for the galley", "caveat": "Cash; best fish go before 9:00; Sunday opening disputed", "dishes": [{"name": "Whole sea bass or bream", "note": "Bought by weight; ask what came in that morning", "kind": "dish"}, {"name": "Octopus", "note": "Sold by weight", "kind": "dish"}, {"name": "Scampi", "note": "For the grill", "kind": "dish"}, {"name": "Cuttlefish", "note": "For black risotto at home or in the galley", "kind": "dish"}], "signal_chip": {"label": "Fish market", "full": "Split's morning fish market, year-round, cash", "cosign": "Time Out: busiest in the morning, best fish sells out early"}, "category": "street", "hot_this_month": "Autumn fish: cuttlefish, squid, grouper and sea bream; arrive early, as the market closes around 13:00 (checked 23 Oct 2026)."},
    {"id": "v10-fife", "cat": "berth", "tier": "berth_top", "priority": 3, "badge": "LOCAL CANTEEN", "name": "Buffet Fife", "neighborhood": "Matejuška", "short": "Fife", "lat": 43.50722, "lng": 16.43412, "tags": [], "productTags": ["Traditional"], "why": "Fife sits on Trumbićeva obala facing the little fishermen's harbour at Matejuška, spread over two buildings: a terrace on the waterfront road, a small room inside and a separate dining room. Nothing is dressed up. Plates arrive fast and heavy, the cooking is home Dalmatian, pašticada with gnocchi, fish soup, fried squid, grilled fish, and the tables mix fishermen, students and tour groups. The city's own Advent programme listed a New Year's party here, which tells you who the regulars are.", "address": "Trumbićeva obala 11, Split", "phone": "+385 21 345 223 (from a search extract; confirm)", "hours": "Year-round per a Split guide (open daily all year); another listing says 'daily in season'. Trading in 2026 (reviews July to September 2026, listing updated 8 Oct 2026); likely open now and into November–December, not confirmed by the house · Call ahead: one guide says daily 10:00–22:00 year-round; another daily 10:00–24:00 in season; a travel listing updated Aug 2026 gives daily 08:00–24:00", "maps": "https://www.google.com/maps/search/?api=1&query=Fife+Split", "price_range": "About EUR 20–30 a head (blog figure, undated; not re-seen in Oct 2026)", "reservation": "Walk-in; bookings reportedly only for large groups", "status": "confirmed", "statusChecked": "2026-10-23", "hook": "The no-frills Dalmatian canteen on the Matejuška waterfront, open all day, where locals and crews eat cheap.", "verdict": "The honest cheap lunch on the waterfront, not a destination for cooking. Portions are big and prices low by Riva standards, and it is one of the few tables here that seems to trade through the winter. Expect queues at peak times and brisk service. Send the crew, not the guests who want a tablecloth.", "signature": "Pašticada with gnocchi, or fried squid if the pašticada has run out", "caveat": "Queues at peak times; reservations reportedly only for large groups; one reviewer found it cash only", "dishes": [{"name": "Pašticada with njoki", "note": "Dalmatian braised beef in a dark prune-and-wine sauce, with gnocchi to soak it up", "kind": "dish"}, {"name": "Fish soup", "note": "The daily soup from the catch", "kind": "dish"}, {"name": "Fried squid (lignje)", "note": "The default plate for a quick waterfront lunch", "kind": "dish"}, {"name": "Grilled fish", "note": "Simple grilled fish, as reviewers describe it", "kind": "dish"}], "signal_chip": {"label": "Local canteen", "full": "Long-running Split canteen on Matejuška; Tripadvisor reviews dated July–September 2026", "cosign": "Listed by the City of Split Advent programme among 'Split locals' venues"}, "category": "street", "hot_this_month": "Pašticada with gnocchi is back in its season, the cold months, at weekday lunch by the fishing harbour (checked 23 Oct 2026)."}
